function layerPanel(){modal('Five drawing layers','<p>Drawing, erasing and lasso selection affect the active layer. Visibility stays on this device.</p><div id="layerRows">'+layers().map((name,i)=>'<div class="layerRow"><input aria-label="Layer '+(i+1)+' name" data-name="'+i+'" value="'+esc(name)+'"><button data-active="'+i+'" class="outline '+(activeLayer===i?'on':'')+'">'+(activeLayer===i?'Active':'Select')+'</button><button data-visible="'+i+'" class="outline">'+(hiddenLayers.get(current.id)?.has(i)?'Show':'Hide')+'</button></div>').join('')+'</div>');$('layerRows').onchange=e=>{if(e.target.dataset.name!==undefined){layers()[+e.target.dataset.name]=e.target.value.slice(0,60);save(current);}};$('layerRows').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.active!==undefined)activeLayer=+b.dataset.active;if(b.dataset.visible!==undefined){const set=hiddenLayers.get(current.id)||new Set(),i=+b.dataset.visible;set.has(i)?set.delete(i):set.add(i);hiddenLayers.set(current.id,set);}selected.clear();drawPage();layerPanel();};}
