async function freezePages(d){let total=0;if(d.originalPDF){const pdf=await openPDF(d.originalPDF);total=pdf.numPages;await pdf.destroy();}d.pages.forEach((p,i)=>{p.id||=uid();p.pdfPage=pdfPageNumber(p,i,total);});}
