confirmPageDeletion=function(){const d=current,n=pg;modal('Move page to Trash?','<p>The page and its annotations can be restored from Trash. It will be excluded from exports.</p><button id="confirmDelete" class="primary">Move page to Trash</button><button id="cancelDelete" class="outline">Cancel</button>');$('cancelDelete').onclick=closeModal;$('confirmDelete').onclick=async()=>{$('confirmDelete').disabled=true;try{await commitPages(d,c=>{c.trashPages||=[];c.trashPages.push({page:c.pages.splice(n,1)[0],position:n,deletedAt:Date.now()});if(!c.pages.length)c.pages.push({...fresh(),id:uid()});});closeModal();notify('Page moved to Trash.');}catch(e){if($('confirmDelete'))$('confirmDelete').disabled=false;notify(e.message);}};};
