async function loadOutline(){const d=current;if(!d.originalPDF)return notify('This notebook has no imported PDF outline.');const pdf=await openPDF(d.originalPDF);try{const outline=await pdf.getOutline(),container=$('outlineRows');if(!outline?.length){container.textContent='This PDF has no outline.';return;}async function append(items,parent,depth=0){for(const item of items){const b=button(item.title,async()=>{try{const dest=typeof item.dest==='string'?await pdf.getDestination(item.dest):item.dest;if(!dest)return;const n=typeof dest[0]==='number'?dest[0]:await pdf.getPageIndex(dest[0]);const i=d.pages.findIndex((p,j)=>pdfPageNumber(p,j,pdf.numPages)===n+1);if(i>=0)pageTo(i);else notify('This destination page has been removed.');}catch{notify('Cannot open this outline destination.');}});b.style.marginLeft=depth*16+'px';parent.append(b);if(item.items)await append(item.items,parent,depth+1);}}await append(outline,container);/* Keep document until outline buttons are dismissed. */const obs=new MutationObserver(()=>{if(!container.isConnected){pdf.destroy();obs.disconnect();}});obs.observe($('editor'),{childList:true,subtree:true});}catch(e){await pdf.destroy();notify(e.message);}}
