async function globalSearch(){modal('Search library contents','<form id="globalFind"><input id="globalQuery" type="search" placeholder="Search typed notes and PDF text" required><button class="primary">Search</button></form><p id="globalStatus">Handwriting and scanned images require OCR and are not indexed.</p><div id="globalResults"></div>');$('globalFind').onsubmit=async e=>{e.preventDefault();const q=$('globalQuery').value.trim().toLowerCase(),out=$('globalResults'),status=$('globalStatus');out.replaceChildren();status.textContent='Searching…';let count=0;const add=(d,i,label)=>{count++;out.append(button(d.title+' · '+label,()=>{closeModal();openDoc(d);pageTo(i);},'menuaction'));};for(const d of docs.filter(d=>!d.deleted&&d.kind!=='elements')){if(!out.isConnected)return;if(d.title.toLowerCase().includes(q))add(d,0,'title');if(JSON.stringify(d.blocks||d.cards||[]).toLowerCase().includes(q))add(d,0,'document content');let pdf;try{if(d.originalPDF)pdf=await openPDF(d.originalPDF);for(let i=0;i<d.pages.length;i++){const p=d.pages[i];let text=p.marks.map(m=>m.text||'').join(' ');const n=pdf&&pdfPageNumber(p,i,pdf.numPages);if(n){const content=await(await pdf.getPage(n)).getTextContent();text+=' '+content.items.map(t=>t.str||'').join(' ');}if(text.toLowerCase().includes(q))add(d,i,'page '+(i+1));if(!out.isConnected)return;}}catch{status.textContent='Some PDF text could not be read.';}finally{await pdf?.destroy();}}status.textContent=count+' results.';};}
$('create').onclick=()=>{modal('Create a workspace','<div id="createKinds"></div>');for(const [kind,title] of [['notebook','Notebook'],['whiteboard','Expandable whiteboard'],['textdoc','Text document'],['study','Study set']])$('createKinds').append(button(title,()=>{closeModal();if(kind==='notebook')return editForm();const name=prompt(title+' name');if(!name)return;const d=make(name,0,view.startsWith('folder:')?view.slice(7):'');d.kind=kind;if(kind==='whiteboard'){d.pages[0]={...fresh(),w:2400,h:1800,template:{pattern:'dots',gap:40}};}if(kind==='textdoc')d.blocks=[{type:'paragraph',text:''}];if(kind==='study')d.cards=[];save(d).then(()=>{docs.push(d);openDoc(d);});},'menuaction'));};
function parseDelimited(text,separator){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===separator&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(quoted)throw Error('Unclosed quote in import.');return rows;}
