function renderStudy(host){const d=current;d.cards||=[];const actions=document.createElement('div');actions.className='specialActions';actions.append(button('Add card',()=>cardDialog()),button('Import CSV / TSV',()=>{const f=document.createElement('input');f.type='file';f.accept='.csv,.tsv,.txt';f.onchange=async()=>{try{const file=f.files[0],text=await file.text(),rows=parseDelimited(text,file.name.endsWith('.csv')?',':'\t');const cards=rows.filter(r=>r.length>=2).map(r=>({id:uid(),question:r[0],answer:r[1],due:0,interval:0}));if(!cards.length)throw Error('Expected question and answer columns.');d.cards.push(...cards);await save(d);drawPage();notify(cards.length+' cards imported.');}catch(e){notify(e.message);}};f.click();}),button('Export CSV',()=>download(new Blob([d.cards.map(c=>[c.question,c.answer].map(s=>'"'+s.replace(/"/g,'""')+'"').join(',')).join('\n')],{type:'text/csv'}),d.title+'.csv')),button('Due cards first',()=>{d.cards.sort((a,b)=>(a.due||0)-(b.due||0));studyIndex=0;studyAnswer=false;drawPage();}));host.append(actions);if(!d.cards.length){host.append(document.createTextNode('Create cards or import two-column questions and answers.'));return;}studyIndex=Math.min(studyIndex,d.cards.length-1);const card=d.cards[studyIndex],face=document.createElement('div');face.className='flashcard';const label=document.createElement('small');label.textContent=(studyIndex+1)+' / '+d.cards.length+' · '+(studyAnswer?'ANSWER':'QUESTION');const text=document.createElement('p');text.textContent=studyAnswer?card.answer:card.question;face.append(label,text);if(card.image){const im=document.createElement('img');im.src=card.image;im.alt='Flashcard image';face.append(im);}host.append(face);const controls=document.createElement('div');controls.className='specialActions';controls.append(button('Previous',()=>{studyIndex=(studyIndex-1+d.cards.length)%d.cards.length;studyAnswer=false;drawPage();}),button(studyAnswer?'Show question':'Reveal answer',()=>{studyAnswer=!studyAnswer;drawPage();},'primary'),button('Next',()=>{studyIndex=(studyIndex+1)%d.cards.length;studyAnswer=false;drawPage();}),button('Edit card',()=>cardDialog(card)));if(studyAnswer)for(const [label,days] of [['Again',0],['Hard',1],['Good',Math.max(2,(card.interval||1)*2)],['Easy',Math.max(4,(card.interval||1)*3)]])controls.append(button(label,()=>{card.interval=days;card.due=Date.now()+days*86400000;save(d);studyIndex=(studyIndex+1)%d.cards.length;studyAnswer=false;drawPage();}));host.append(controls);}
function cardDialog(card){modal(card?'Edit flashcard':'New flashcard','<label>Question</label><textarea id="question" rows="3"></textarea><label>Answer</label><textarea id="answer" rows="4"></textarea><button id="cardImage" class="outline">Attach image</button><button id="saveCard" class="primary">Save card</button>'+(card?'<button id="removeCard" class="outline">Delete card</button>':''));$('question').value=card?.question||'';$('answer').value=card?.answer||'';let image=card?.image;$('cardImage').onclick=async()=>{const im=await chooseImage();if(im){image=im.src;$('cardImage').textContent='Image attached';}};$('saveCard').onclick=()=>{const q=$('question').value,a=$('answer').value;if(!q||!a)return notify('Enter a question and answer.');const c={id:card?.id||uid(),question:q,answer:a,image,interval:card?.interval||0,due:card?.due||0};if(card)Object.assign(card,c);else current.cards.push(c);save(current);closeModal();drawPage();};if(card)$('removeCard').onclick=()=>{if(confirm('Delete this flashcard?')){current.cards=current.cards.filter(c=>c!==card);save(current);closeModal();drawPage();}};}
function renderBlocks(host){const d=current;d.blocks||=[];const actions=document.createElement('div');actions.className='specialActions';for(const type of ['paragraph','h1','h2','h3','list','quote','code','table','image','video'])actions.append(button('+ '+type,async()=>{const block={id:uid(),type,text:''};if(type==='image'){const im=await chooseImage();if(!im)return;block.src=im.src;}d.blocks.push(block);await save(d);drawPage();}));actions.append(button('Export HTML',()=>{const wrap=document.createElement('div');for(const block of d.blocks)wrap.append(blockView(block));download(new Blob(['<!doctype html><meta charset="utf-8"><title>'+esc(d.title)+'</title><article>'+wrap.innerHTML+'</article>'],{type:'text/html'}),d.title+'.html');}));host.append(actions);for(const [i,block]of d.blocks.entries()){const row=document.createElement('div');row.className='textBlock';row.append(blockView(block));const controls=document.createElement('div');controls.className='blockControls';controls.append(button('Edit',()=>editBlock(block)),button('↑',()=>{if(i){d.blocks.splice(i-1,0,d.blocks.splice(i,1)[0]);save(d);drawPage();}}),button('↓',()=>{if(i<d.blocks.length-1){d.blocks.splice(i+1,0,d.blocks.splice(i,1)[0]);save(d);drawPage();}}),button('Delete',()=>{if(confirm('Delete this block?')){d.blocks.splice(i,1);save(d);drawPage();}}));row.append(controls);host.append(row);}}
function blockView(block){let el;const types={paragraph:'p',h1:'h1',h2:'h2',h3:'h3',quote:'blockquote',code:'pre',list:'ul'};if(block.type==='image'){el=document.createElement('img');el.src=block.src;el.alt=block.text||'Document image';}else if(block.type==='video'){el=document.createElement('a');el.textContent=block.text||'Edit to enter a video URL';if(/^https?:\/\//i.test(block.text||'')){el.href=block.text;el.target='_blank';el.rel='noopener noreferrer';}}else if(block.type==='table'){el=document.createElement('table');for(const line of (block.text||'Column 1\tColumn 2\nCell\tCell').split('\n')){const row=el.insertRow();for(const value of line.split('\t'))row.insertCell().textContent=value;}}else{el=document.createElement(types[block.type]||'p');if(block.type==='list')for(const line of (block.text||'').split('\n')){const li=document.createElement('li');li.textContent=line;el.append(li);}else el.textContent=block.text||'Click Edit to write…';}if(block.bold)el.style.fontWeight='bold';if(block.italic)el.style.fontStyle='italic';if(block.strike)el.style.textDecoration='line-through';return el;}
function editBlock(block){modal('Edit '+block.type,'<p>Tables: tab separates columns, new line separates rows. Video blocks store a web link.</p><textarea id="blockText" rows="10"></textarea><div class="checkRow"><label><input id="blockBold" type="checkbox">Bold</label><label><input id="blockItalic" type="checkbox">Italic</label><label><input id="blockStrike" type="checkbox">Strikethrough</label></div><button id="saveBlock" class="primary">Save block</button>');$('blockText').value=block.text||'';for(const key of ['Bold','Italic','Strike'])$('block'+key).checked=!!block[key.toLowerCase()];$('saveBlock').onclick=()=>{block.text=$('blockText').value;for(const key of ['Bold','Italic','Strike'])block[key.toLowerCase()]=$('block'+key).checked;save(current);closeModal();drawPage();};}
async function ensurePDFLib(){if(window.PDFLib)return;await new Promise((ok,no)=>{const s=document.createElement('script');s.src='./pdf-lib.min.js';s.onload=ok;s.onerror=()=>no(Error('PDF export library unavailable'));document.head.append(s);});}
async function rasterPage(d,p,index,{background=true,annotations=true,scale=1.5}={},source){const c=document.createElement('canvas');scale=Math.min(scale,3000/Math.max(p.w,p.h));c.width=Math.ceil(p.w*scale);c.height=Math.ceil(p.h*scale);const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);if(background){const n=source&&pdfPageNumber(p,index,source.numPages);if(n){await(await source.getPage(n)).render({canvasContext:ctx,viewport:(await source.getPage(n)).getViewport({scale})}).promise;}else if(p.image){const im=new Image();im.src=p.image;await im.decode();ctx.drawImage(im,0,0,c.width,c.height);}else{const bg=element('svg',{xmlns:'http://www.w3.org/2000/svg',width:c.width,height:c.height,viewBox:`0 0 ${p.w} ${p.h}`});bg.append(backgroundSVG(p));await drawSVG(ctx,bg);}}if(annotations){const svg=element('svg',{xmlns:'http://www.w3.org/2000/svg',width:c.width,height:c.height,viewBox:`0 0 ${p.w} ${p.h}`});svg.append(...orderedMarks(p,false).map(o=>mark(o.m.type==='tape'?{...o.m,id:undefined}:o.m)));await drawSVG(ctx,svg);}return c;}
async function drawSVG(ctx,svg){const im=new Image();im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(svg));await im.decode();ctx.drawImage(im,0,0);}
function rgbHex(hex){return PDFLib.rgb(...[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255));}
async function vectorMark(pdf,dest,m,p,font){
 const b=bounds(m),[x,y]=m.points[0],last=m.points.at(-1),col=rgbHex(m.color),opacity=m.type==='highlight'?.34:1,rotation=m.rotation?PDFLib.degrees(-m.rotation):undefined;
 // Render complex/transformed objects individually, leaving original PDF objects untouched.
 if(m.rotation||m.patternImage||m.type==='sticky'||m.type==='text'&&/[^\x20-\x7e\n]/.test(m.text||'')){
  const svg=element('svg',{xmlns:'http://www.w3.org/2000/svg',width:p.w,height:p.h,viewBox:`0 0 ${p.w} ${p.h}`});svg.append(mark(m.type==='tape'?{...m,id:undefined}:m));const canvas=document.createElement('canvas');const ratio=Math.min(1,2400/Math.max(p.w,p.h));canvas.width=p.w*ratio;canvas.height=p.h*ratio;svg.setAttribute('width',canvas.width);svg.setAttribute('height',canvas.height);await drawSVG(canvas.getContext('2d'),svg);const im=await pdf.embedPng(canvas.toDataURL());dest.drawImage(im,{x:0,y:0,width:p.w,height:p.h});return;
 }
 if(m.type==='image'){const im=await pdf.embedPng(m.src);dest.drawImage(im,{x:b.x,y:p.h-b.y-b.h,width:b.w,height:b.h});return;}
 if(m.type==='text'){dest.drawText(m.text||'',{x,y:p.h-y,size:m.fontSize||16+m.width*2,font,color:col,lineHeight:(m.fontSize||22)*1.3});return;}
 const dash=m.style==='dashed'?[m.width*4,m.width*2]:m.style==='dotted'?[1,m.width*2.5]:undefined;
 if(m.type==='rect'){dest.drawRectangle({x:b.x,y:p.h-b.y-b.h,width:b.w,height:b.h,borderColor:col,borderWidth:m.width,borderDashArray:dash,color:undefined});return;}
 if(m.type==='ellipse'){dest.drawEllipse({x:b.x+b.w/2,y:p.h-b.y-b.h/2,xScale:Math.max(.1,b.w/2),yScale:Math.max(.1,b.h/2),borderColor:col,borderWidth:m.width,color:undefined});return;}
 let points=['line','arrow'].includes(m.type)?[[x,y],last]:m.points;
 if(points.length===1)points=[points[0],[points[0][0]+.1,points[0][1]+.1]];
 for(let i=1;i<points.length;i++){const a=points[i-1],z=points[i],pressure=m.pressures?.[i]??.5,weight=m.type==='pen'&&m.penStyle&&m.penStyle!=='ballpoint'?m.width*(.3+pressure*(m.sensitivity||1)*(m.penStyle==='brush'?2.4:1.5)):m.width;dest.drawLine({start:{x:a[0],y:p.h-a[1]},end:{x:z[0],y:p.h-z[1]},thickness:weight,color:col,opacity,lineCap:PDFLib.LineCapStyle.Round,dashArray:dash});}
 if(m.type==='arrow'){const a=Math.atan2(last[1]-y,last[0]-x);for(const delta of [-.5,.5])dest.drawLine({start:{x:last[0],y:p.h-last[1]},end:{x:last[0]-14*Math.cos(a+delta),y:p.h-last[1]+14*Math.sin(a+delta)},thickness:m.width,color:col});}
}
async function buildPDF(d,opts={mode:'flattened',background:true,annotations:true}){
 await ensurePDFLib();const source=d.originalPDF?await openPDF(d.originalPDF):null;let pdf;
 try{
  if(opts.mode==='vector'&&d.originalPDF&&opts.background){pdf=await PDFLib.PDFDocument.load(d.originalPDF);const originals=pdf.getPages(),copySource=await PDFLib.PDFDocument.load(d.originalPDF);const unchanged=d.pages.length===originals.length&&d.pages.every((p,i)=>pdfPageNumber(p,i,originals.length)===i+1);if(!unchanged){for(let i=pdf.getPageCount()-1;i>=0;i--)pdf.removePage(i);for(const [i,p]of d.pages.entries()){const n=pdfPageNumber(p,i,originals.length);if(n){const [copy]=await pdf.copyPages(copySource,[n-1]);stripInternalPDFLinks(copy);pdf.addPage(copy);}else pdf.addPage([p.w,p.h]);}pdf.catalog.delete(PDFLib.PDFName.of('Outlines'));} }
  else pdf=await PDFLib.PDFDocument.create();
  const font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica);
  for(const [i,p]of d.pages.entries()){
   if(opts.mode==='flattened'){const c=await rasterPage(d,p,i,opts,source),im=await pdf.embedPng(c.toDataURL());pdf.addPage([p.w,p.h]).drawImage(im,{x:0,y:0,width:p.w,height:p.h});continue;}
   const dest=pdf.getPages()[i]||pdf.addPage([p.w,p.h]),n=source&&pdfPageNumber(p,i,source.numPages);
   if(opts.background&&!n){const c=await rasterPage(d,p,i,{background:true,annotations:false},null),im=await pdf.embedPng(c.toDataURL());dest.drawImage(im,{x:0,y:0,width:p.w,height:p.h});}
   if(opts.annotations)for(const {m}of orderedMarks(p,false))await vectorMark(pdf,dest,m,p,font);
  }
  if(opts.mode==='vector'&&opts.annotations)addPDFLinks(pdf,d);pdf.setTitle(d.title);return new Blob([await pdf.save()],{type:'application/pdf'});
 }finally{await source?.destroy();}
}
exportPDF=async function(d){download(await buildPDF(d),d.title+'.pdf');notify('Flattened PDF exported.');};
function exportPanel(d){if(['textdoc','study','elements'].includes(d.kind))return notify('Use the export controls inside this workspace, or export a BetterNotes backup.');modal('Export '+d.title,'<label>Format</label><select id="exportMode"><option value="flattened">Flattened PDF — maximum visual compatibility</option><option value="vector">Vector PDF — preserve source PDF and basic ink vectors</option><option value="png">Current page as PNG</option><option value="backup">BetterNotes editable backup</option></select><label class="check"><input id="includeBackground" type="checkbox" checked> Include background / source PDF</label><label class="check"><input id="includeAnnotations" type="checkbox" checked> Include BetterNotes annotations</label><p>Vector export is not a full PDF annotation editor. Complex objects may be images. Original outlines are retained only when PDF page order is unchanged. For lossless BetterNotes editing, use the editable backup.</p><button id="runExport" class="primary">Export</button>');$('runExport').onclick=async()=>{const mode=$('exportMode').value,background=$('includeBackground').checked,annotations=$('includeAnnotations').checked;$('runExport').disabled=true;try{if(mode==='backup')download(new Blob([JSON.stringify(d)],{type:'application/json'}),d.title+'.betternotes');else if(mode==='png'){const n=current===d?pg:0,source=d.originalPDF?await openPDF(d.originalPDF):null;try{const c=await rasterPage(d,d.pages[n],n,{background,annotations},source);download(await new Promise(ok=>c.toBlob(ok)),d.title+'-page-'+(n+1)+'.png');}finally{await source?.destroy();}}else download(await buildPDF(d,{mode,background,annotations}),d.title+'.pdf');closeModal();notify('Export complete.');}catch(e){$('runExport').disabled=false;notify('Export failed: '+e.message);}};}
function safeFilename(s){return s.replace(/[<>:"\\|?*\x00-\x1f]/g,'_').replace(/^\.+$/,'_')||'Untitled';}
function folderExportPanel(){modal('Export folder','<label>Folder</label><select id="exportFolder"><option value="">Entire library</option>'+folders.map(f=>'<option>'+esc(f)+'</option>').join('')+'</select><label>Format</label><select id="folderFormat"><option value="backup">Editable BetterNotes backups</option><option value="pdf">Flattened PDFs (notebooks only)</option></select><button id="zipFolder" class="primary">Download ZIP</button>');$('zipFolder').onclick=async()=>{const path=$('exportFolder').value,mode=$('folderFormat').value;$('zipFolder').disabled=true;try{const zip=new JSZip();for(const f of folders)if(!path||f===path||f.startsWith(path+'/'))zip.folder(f.split('/').map(safeFilename).join('/'));for(const d of docs.filter(d=>!d.deleted&&(!path||d.folder===path||d.folder?.startsWith(path+'/')))){if(mode==='pdf'&&['textdoc','study','elements'].includes(d.kind))continue;const dest=(d.folder?d.folder.split('/').map(safeFilename).join('/')+'/':'')+safeFilename(d.title)+'-'+d.id.slice(0,6);zip.file(dest+(mode==='pdf'?'.pdf':'.betternotes'),mode==='pdf'?await buildPDF(d):JSON.stringify(d));}download(await zip.generateAsync({type:'blob'}),'BetterNotes-folder.zip');closeModal();}catch(e){$('zipFolder').disabled=false;notify(e.message);}};}
function mergePanel(){const candidates=docs.filter(d=>!d.deleted&&!['study','textdoc','elements'].includes(d.kind));modal('Merge notebooks','<p>Creates a new notebook in the order listed. Originals remain available. Source PDF outlines are not transferred.</p><div id="mergeChoices">'+candidates.map(d=>'<label class="check"><input type="checkbox" value="'+d.id+'">'+esc(d.title)+'</label>').join('')+'</div><label>Merged title</label><input id="mergeTitle" value="Merged notebook"><button id="mergeNow" class="primary">Merge selected</button>');$('mergeNow').onclick=async()=>{const ids=[...$('mergeChoices').querySelectorAll(':checked')].map(e=>e.value);if(ids.length<2)return notify('Select at least two notebooks.');$('mergeNow').disabled=true;try{await ensurePDFLib();const pdf=await PDFLib.PDFDocument.create(),pages=[];for(const id of ids){const d=docs.find(d=>d.id===id);await freezePages(d);const src=d.originalPDF?await PDFLib.PDFDocument.load(d.originalPDF):null;for(const p of d.pages){const n=src&&pdfPageNumber(p,0,src.getPageCount());if(n){const [copy]=await pdf.copyPages(src,[n-1]);pdf.addPage(copy);}else{const dest=pdf.addPage([p.w,p.h]);{const im=await pdf.embedPng((await rasterPage(d,p,0,{annotations:false})).toDataURL());dest.drawImage(im,{x:0,y:0,width:p.w,height:p.h});}}const copy=structuredClone(p);copy.id=uid();copy.pdfPage=pages.length+1;pages.push(copy);}}const d=make($('mergeTitle').value.trim()||'Merged notebook',0,'',pages);d.originalPDF=await dataURL(new Blob([await pdf.save()],{type:'application/pdf'}));await save(d);docs.push(d);closeModal();openDoc(d);}catch(e){$('mergeNow').disabled=false;notify(e.message);}};}
function audioPanel(){modal('Audio recordings','<p>Record audio with page bookmarks while BetterNotes is open. Microphone permission is required. Recordings are stored with the notebook and included in backups and Drive sync.</p><div id="audioActions"></div><div id="recordings"></div>');$('audioActions').append(button(recording?'Stop recording':'Start recording',async()=>{if(recording){recording.rec.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return notify('Audio recording is not supported in this browser.');try{const d=current,stream=await navigator.mediaDevices.getUserMedia({audio:true}),rec=new MediaRecorder(stream),chunks=[],started=Date.now(),marks=[{ms:0,pageId:page().id}];recording={rec,stream,doc:d,marks,started};rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};rec.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());recording=null;const blob=new Blob(chunks,{type:rec.mimeType});d.recordings||=[];d.recordings.push({id:uid(),name:new Date(started).toLocaleString(),src:await dataURL(blob),marks});await save(d);notify('Recording saved.');if($('recordings'))audioPanel();};rec.start(1000);audioPanel();}catch(e){notify('Cannot start recording: '+e.message);}}));if(recording)$('audioActions').append(button('Bookmark current page',()=>{recording.marks.push({ms:Date.now()-recording.started,pageId:page().id});notify('Audio page bookmark added.');}));for(const rec of current.recordings||[]){const row=document.createElement('div');row.className='recording';row.append(document.createTextNode(rec.name));const audio=document.createElement('audio');audio.controls=true;audio.src=rec.src;row.append(audio);for(const m of rec.marks||[])row.append(button(Math.floor(m.ms/1000)+'s · page',()=>{const i=current.pages.findIndex(p=>p.id===m.pageId);if(i>=0)pageTo(i);audio.currentTime=m.ms/1000;audio.play();}));row.append(button('Delete recording',()=>{if(confirm('Delete this recording?')){current.recordings=current.recordings.filter(r=>r!==rec);save(current);audioPanel();}}));$('recordings').append(row);}}
async function uploadDriveBlob(folder,name,blob,properties={}){const boundary='bn_'+uid(),meta={name,parents:[folder],appProperties:properties},body=new Blob(['--'+boundary+'\r\nContent-Type: application/json\r\n\r\n',JSON.stringify(meta),'\r\n--'+boundary+'\r\nContent-Type: '+(blob.type||'application/octet-stream')+'\r\n\r\n',blob,'\r\n--'+boundary+'--']);return driveFetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,webViewLink',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+boundary},body});}
async function backupFolder(){let rows=await listFiles("appProperties has { key='bnBackupFolder' and value='1' }");if(!rows.length)rows=[await driveFetch(api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'BetterNotes Backups',mimeType:'application/vnd.google-apps.folder',appProperties:{bnBackupFolder:'1'}})})];return rows[0].id;}
let backingUp=false;
async function runBackup(){if(backingUp)return;if(!token||Date.now()>expiry)return notify('Connect Google Drive before creating a cloud backup.');backingUp=true;try{await busySave;const folder=await backupFolder(),stamp=new Date().toISOString().replace(/[:.]/g,'-');for(const d0 of docs.filter(d=>!d.deleted)){const d=structuredClone(d0);await uploadDriveBlob(folder,safeFilename(d.title)+'-'+stamp+'.betternotes',new Blob([JSON.stringify(d)],{type:'application/json'}),{bnBackup:'1'});if(!['study','textdoc','elements'].includes(d.kind))await uploadDriveBlob(folder,safeFilename(d.title)+'-'+stamp+'.pdf',await buildPDF(d),{bnBackup:'1'});}localStorage.bnLastBackup=String(Date.now());notify('Independent Drive snapshots saved.');}catch(e){notify('Backup incomplete: '+e.message);}finally{backingUp=false;}}
function backupPanel(){modal('Backups and sharing','<p>Sync updates your working library. Backups create separate, dated PDF and editable copies in “BetterNotes Backups” on Drive. Existing snapshots are never replaced or deleted by this app.</p><p>Scheduled backups run only while this app is open and Google authorization is valid. Last completed: '+(localStorage.bnLastBackup?esc(new Date(+localStorage.bnLastBackup).toLocaleString()):'Never')+'</p><label class="check"><input id="autoBackup" type="checkbox" '+(prefs.autoBackup?'checked':'')+'> Enable scheduled backups</label><label>Interval (hours)</label><input id="backupHours" type="number" min="1" max="168" value="'+prefs.backupHours+'"><button id="saveBackup" class="primary">Save backup settings</button><button id="backupNow" class="outline">Back up now</button><button id="driveConnect" class="outline">Google Drive connection</button><p>To share a document, use its notebook options → Share PDF via Google Drive. Public sharing requires a separate confirmation.</p>');$('saveBackup').onclick=()=>{const n=+$('backupHours').value;if(n<1||n>168)return;prefs.autoBackup=$('autoBackup').checked;prefs.backupHours=n;persistPrefs();closeModal();};$('backupNow').onclick=()=>{closeModal();runBackup();};$('driveConnect').onclick=drivePanel;}
setInterval(()=>{if(prefs.autoBackup&&!document.hidden&&token&&Date.now()-(+localStorage.bnLastBackup||0)>prefs.backupHours*3600000)runBackup();},60000);
async function shareDocument(d){if(!token)return drivePanel();if(['textdoc','study','elements'].includes(d.kind))return notify('Public PDF sharing currently supports notebooks and whiteboards. Export other workspaces from their own controls.');modal('Share '+d.title,'<p>Create a PDF snapshot on Google Drive. Choose private to keep it restricted, or anyone-with-link to make the contents publicly accessible to people with the link. Later notebook edits do not update this snapshot.</p><button id="sharePrivate" class="outline">Create private PDF</button><button id="sharePublic" class="primary">Create anyone-with-link PDF</button>');async function run(publicLink){$('sharePrivate').disabled=$('sharePublic').disabled=true;try{const f=await uploadDriveBlob(await backupFolder(),safeFilename(d.title)+'-shared.pdf',await buildPDF(d),{bnShared:'1'});if(publicLink)await driveFetch(api+'/'+f.id+'/permissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'anyone',role:'reader'})});modal('PDF snapshot created','<p>'+ (publicLink?'Anyone with this link can read this PDF.':'This file is private to your Google account.')+'</p><p><a target="_blank" rel="noopener noreferrer" href="https://drive.google.com/file/d/'+encodeURIComponent(f.id)+'/view">Open shared PDF in Google Drive</a></p><p>You can revoke access in Google Drive → Share.</p>');}catch(e){notify(e.message);$('sharePrivate').disabled=$('sharePublic').disabled=false;}}$('sharePrivate').onclick=()=>run(false);$('sharePublic').onclick=()=>run(true);}
// Backup imports preserve custom workspace types and objects. Never execute imported markup.
const baseValidDoc=validDoc;
validDoc=function(d){if(!baseValidDoc(d))return false;const safeImage=s=>typeof s==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s);for(const p of d.pages){if(!Number.isFinite(p.w)||!Number.isFinite(p.h)||p.w>50000||p.h>50000)return false;for(const m of p.marks){if(m.type==='image'&&!safeImage(m.src)||m.patternImage&&!safeImage(m.patternImage))return false;if(m.layer!==undefined&&(!Number.isInteger(m.layer)||m.layer<0||m.layer>4))return false;if(m.rotation!==undefined&&!Number.isFinite(m.rotation))return false;}}if(d.blocks&&(!Array.isArray(d.blocks)||d.blocks.some(b=>b.type==='image'&&!safeImage(b.src))))return false;if(d.cards&&(!Array.isArray(d.cards)||d.cards.some(c=>typeof c.question!=='string'||typeof c.answer!=='string'||c.image&&!safeImage(c.image))))return false;return true;};
const baseReadDocument=readDocument;
readDocument=async function(name,blob){if(/\.zip$/i.test(name)){const zip=await JSZip.loadAsync(blob);let count=0;for(const entry of Object.values(zip.files)){if(entry.name.startsWith('__MACOSX/')||entry.name.split('/').includes('..'))continue;if(entry.dir){const dir=entry.name.replace(/\/+$/,'');if(dir&&!folders.includes(dir))folders.push(dir);continue;}if(/\.(pdf|png|jpe?g|betternotes|inkfolio)$/i.test(entry.name)){await readDocument(entry.name,await entry.async('blob'));count++;}}localStorage.folders=JSON.stringify(folders);if(!count)throw Error('No supported PDF, image or BetterNotes backup files in ZIP.');return;}return baseReadDocument(name,blob);};
// Keyboard actions do not intercept typing in forms, block editors, or dialogs.
 document.addEventListener('keydown',e=>{if(!current||$('modal').open||e.target.closest('input,textarea,select,[contenteditable]'))return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(mod&&['c','x','v'].includes(key)){if(key!=='v'&&!selected.size)return;e.preventDefault();if(key==='c'||key==='x')copySelection();if(key==='x')deleteSelection();if(key==='v')pasteSelection();return;}if(e.key==='Delete'&&selected.size){e.preventDefault();deleteSelection();return;}if(mod)return;const keys={p:'pen',h:'highlight',e:'erase',l:'lasso',v:'read',t:'text'};if(keys[key]){tool=keys[key];drawPage();}if(e.key==='ArrowRight'||e.key==='PageDown')pageTo(pg+1);if(e.key==='ArrowLeft'||e.key==='PageUp')pageTo(pg-1);if(e.key==='Home')pageTo(0);if(e.key==='End')pageTo(current.pages.length-1);});
let deferredInstall;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});$('install').onclick=async()=>{if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;return;}modal('Install BetterNotes','<p><b>iPhone / iPad:</b> Safari → Share → Add to Home Screen.</p><p><b>Mac:</b> Safari → File → Add to Dock.</p><p><b>Windows / Android:</b> Chrome or Edge → browser menu → Install BetterNotes / Install app.</p>');};
window.addEventListener('beforeunload',e=>{if(recording){e.preventDefault();e.returnValue='Recording in progress';}});
window.addEventListener('storage',e=>{if(e.key==='bnLibraryChanged'&&!current)req(db.transaction('books').objectStore('books').getAll()).then(rows=>{docs=rows;render();});});
const oldWrite=write;write=async function(d){await oldWrite(d);localStorage.bnLibraryChanged=String(Date.now());};

window.addEventListener("load",()=>{if(db&&!current)render();});
// Alignment is relative to the selected objects' unrotated bounds.
function alignSelection(direction){const marks=[...selected].map(i=>page().marks[i]).filter(m=>!m.locked);if(marks.length<2)return notify('Select at least two unlocked objects.');const boxes=marks.map(bounds),left=Math.min(...boxes.map(b=>b.x)),right=Math.max(...boxes.map(b=>b.x+b.w)),top=Math.min(...boxes.map(b=>b.y)),bottom=Math.max(...boxes.map(b=>b.y+b.h));checkpoint();marks.forEach(m=>{const b=bounds(m);moveMark(m,direction==='left'?left-b.x:direction==='center'?(left+right-b.w)/2-b.x:0,direction==='top'?top-b.y:0);});save(current);drawPage();}
const baseSelection=drawSelection;drawSelection=function(){baseSelection();if(selected.size>1){const bar=$('selectionBar');for(const dir of ['left','center','top'])bar.append(button('Align '+dir,()=>alignSelection(dir)));}};
// Layer visibility is local; never alters another device's view or export data.
const originalHideMap=hiddenLayers;
function boardMap(){let map=$('boardMap');if(current?.kind!=='whiteboard'){map?.remove();return;}if(!map){map=document.createElement('div');map.id='boardMap';$('paperWrap').after(map);}map.replaceChildren();const p=page(),svg=element('svg',{viewBox:`0 0 ${p.w} ${p.h}`,width:180,height:120});svg.append(element('rect',{width:p.w,height:p.h,fill:'#f9fffc'}),...orderedMarks(p).map(o=>mark(o.m)));svg.onclick=e=>{const r=svg.getBoundingClientRect(),wrap=$('paperWrap'),paper=$('paper');wrap.scrollLeft=(e.clientX-r.left)/r.width*paper.clientWidth-wrap.clientWidth/2;wrap.scrollTop=(e.clientY-r.top)/r.height*paper.clientHeight-wrap.clientHeight/2;};map.append(svg,button('Fit board',()=>{plainZoom=Math.min(1,$('paperWrap').clientHeight/page().h);drawPage();}),button('Expand',()=>{if(p.w>=20000||p.h>=20000)return notify('Board limit reached. Create another board.');p.w+=1000;p.h+=1000;save(current);drawPage();}));}
const completeDraw=drawPage;drawPage=function(){completeDraw();boardMap();};
function stripInternalPDFLinks(p){const {PDFName,PDFArray,PDFDict}=PDFLib,list=p.node.lookupMaybe(PDFName.of('Annots'),PDFArray);if(!list)return;for(let i=list.size()-1;i>=0;i--){const a=list.lookupMaybe(i,PDFDict);if(!a)continue;const action=a.lookupMaybe(PDFName.of('A'),PDFDict);if(a.has(PDFName.of('Dest'))||action?.get(PDFName.of('S'))?.toString()==='/GoTo')list.remove(i);}}
function addPDFLinks(pdf,d){const {PDFName}=PDFLib;for(const [i,p]of d.pages.entries())for(const m of p.marks){if(!m.link)continue;const b=bounds(m),entry={Type:'Annot',Subtype:'Link',Rect:[b.x,p.h-b.y-b.h,b.x+b.w,p.h-b.y+24],Border:[0,0,0]};if(m.link.pageId){const n=d.pages.findIndex(p=>p.id===m.link.pageId);if(n<0)continue;entry.Dest=[pdf.getPages()[n].ref,'Fit'];}else if(/^https?:\/\//i.test(m.link.url||''))entry.A={S:'URI',URI:PDFLib.PDFString.of(m.link.url)};else continue;const ref=pdf.context.register(pdf.context.obj(entry)),dest=pdf.getPages()[i];const annots=dest.node.Annots();if(annots)annots.push(ref);else dest.node.set(PDFName.of('Annots'),pdf.context.obj([ref]));}}
function tapeSettings(){modal('Tape appearance','<p>Choose a solid mask or a repeating image pattern. Tape width follows the current stroke width multiplied by six.</p><button id="solidTape" class="outline">Solid color</button><button id="patternTape" class="outline">Import pattern image</button>');$('solidTape').onclick=()=>{delete prefs.tapeImage;prefs.tapePattern='solid';persistPrefs();closeModal();};$('patternTape').onclick=async()=>{const im=await chooseImage();if(im){prefs.tapeImage=im.src;persistPrefs();closeModal();notify('Pattern ready for new tape strokes.');}};}
toolset.erase=['eraser','Eraser · erase strokes or split ink; configure in Tool settings'];
let thumbnailObserver;
const basePagePanel=renderPagePanel;
renderPagePanel=function(){thumbnailObserver?.disconnect();basePagePanel();if(!pagePanelOpen||!current?.originalPDF)return;const d=current,panel=$('pagePanel');thumbnailObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;thumbnailObserver.unobserve(entry.target);const i=+entry.target.dataset.page,p=d.pages[i],holder=entry.target.querySelector('.pageThumb');pdfViewer.getDocument(d).then(source=>rasterPage(d,p,i,{scale:Math.min(65/p.w,80/p.h)},source)).then(canvas=>{if(current!==d||!panel.isConnected||!holder.isConnected)return;canvas.style.width='65px';canvas.style.height='80px';canvas.style.objectFit='contain';holder.querySelector('svg')?.replaceWith(canvas);}).catch(()=>{});}}, {root:$('pageCards'),rootMargin:'100px'});for(const node of panel.querySelectorAll('.pageCard'))thumbnailObserver.observe(node);};
const safePageTo=pageTo;
pageTo=function(n){if(!current||!Number.isInteger(n)||n<0||n>=current.pages.length||gesture)return;if(n!==pg)selected.clear();safePageTo(n);};
const safeHistoryStep=historyStep;
historyStep=function(forward){selected.clear();safeHistoryStep(forward);};
